function summarizeWindow(events, nowMs, windowMs, cap) {
  // 1) Deduplicate raw events by non-empty string id, keeping the FIRST occurrence.
  const seenIds = new Set();
  const deduped = [];
  for (const ev of events) {
    const id = ev && typeof ev === 'object' ? ev.id : undefined;
    if (typeof id === 'string' && id.length > 0) {
      if (seenIds.has(id)) continue;
      seenIds.add(id);
    }
    deduped.push(ev);
  }

  // 2) Apply the qualifying filter.
  const start = nowMs - windowMs;
  const counts = new Map();
  let used = 0;
  let minTs = Infinity;

  for (const ev of deduped) {
    if (!ev || typeof ev !== 'object') continue;

    const ts = ev.ts;
    if (typeof ts !== 'number' || !Number.isFinite(ts)) continue;
    if (ts < start || ts > nowMs) continue;

    if (ev.provider !== 'opencode-go') continue;
    if (ev.error) continue;

    const model = ev.model;
    if (typeof model !== 'string') continue;
    if (model.toLowerCase().endsWith('-free')) continue;

    used += 1;
    if (ts < minTs) minTs = ts;

    let short = model;
    if (short.startsWith('opencode-go/')) {
      short = short.slice('opencode-go/'.length);
    }
    short = short.toLowerCase();
    counts.set(short, (counts.get(short) || 0) + 1);
  }

  // 3) Build byModel with alphabetically sorted keys.
  const byModel = {};
  for (const key of [...counts.keys()].sort()) {
    byModel[key] = counts.get(key);
  }

  return {
    used,
    remaining: Math.max(0, cap - used),
    pct: Math.round((used / cap) * 1000) / 10,
    overCap: used > cap,
    oldestExpiresAt: used === 0 ? null : minTs + windowMs,
    byModel,
  };
}
